  // Estrellas de fondo extraídas de la foto (suavizadas para que solo destaquen las 3 brillantes + la central)
  const landmarkStars = LANDMARK_STARS_DATA.map((item) => {
    const [u, v, radius, colorType] = item;
    const nx = mapPhotoX(u);
    const ny = v;
    let nearSpecial = false;
    for (let i = 0; i < MESSAGE_STARS.length; i++) {
      if (Math.hypot(nx - MESSAGE_STARS[i].nx, ny - MESSAGE_STARS[i].ny) < 0.015) {
        nearSpecial = true;
        break;
      }
    }
    return {
      nx,
      ny,
      radius: nearSpecial ? radius * 0.25 : Math.min(1.5, radius * 0.64),
      colorType,
      phase: random() * Math.PI * 2,
      speed: 0.3 + random() * 0.75
    };
  });

